import pandas as pd
from collections import defaultdict

def analyze_hierarchy(employees: pd.DataFrame) -> pd.DataFrame:
    children = defaultdict(list)
    salaries = {}
    names = {}
    ceo_id = None
    for _, row in employees.iterrows():
        eid = int(row['employee_id'])
        mid = row['manager_id']
        salaries[eid] = int(row['salary'])
        names[eid] = row['employee_name']
        if pd.isna(mid) or mid is None:
            ceo_id = eid
        else:
            children[int(mid)].append(eid)

    levels = {}
    if ceo_id is not None:
        q = [(ceo_id, 1)]
        while q:
            curr, lvl = q.pop(0)
            levels[curr] = lvl
            for ch in children[curr]:
                q.append((ch, lvl + 1))

    sub_count = {}
    budgets = {}
    def dfs(u):
        cnt = 0
        total_sal = salaries[u]
        for v in children[u]:
            c, s = dfs(v)
            cnt += 1 + c
            total_sal += s
        sub_count[u] = cnt
        budgets[u] = total_sal
        return cnt, total_sal

    if ceo_id is not None:
        dfs(ceo_id)

    records = []
    for eid in salaries:
        records.append({
            'employee_id': eid,
            'employee_name': names[eid],
            'level': levels.get(eid, 1),
            'team_size': sub_count.get(eid, 0),
            'budget': budgets.get(eid, salaries[eid])
        })
    res_df = pd.DataFrame(records)
    return res_df.sort_values(
        by=['level', 'budget', 'employee_name'],
        ascending=[True, False, True]
    ).reset_index(drop=True)
